  "ref": "職業安全衛生設施規則§第318條",
  "law": "《職業安全衛生設施規則》第318條：雇主對於勞工從事其身體或衣著有被污染之虞之特殊作業時，應置備該勞工洗眼、洗澡、漱口、更衣、洗滌等設備。前項設備，應依下列規定設置：\n\n一、刺激物、腐蝕性物質或毒性物質污染之工作場所，每十五人應設置一個冷熱水沖淋設備。\n\n二、刺激物、腐蝕性物質或毒性物質污染之工作場所，每五人應設置一個冷熱水盥洗設備。",
