  "law": "《危險性工作場所審查及檢查辦法》第4條：事業單位應於甲類工作場所、丁類工作場所使勞工作業三十日前，向當地勞動檢查機構（以下簡稱檢查機構）申請審查。\n\n事業單位應於乙類工作場所、丙類工作場所使勞工作業四十五日前，向檢查機構申請審查及檢查。",
