  "ref": "營造安全衛生設施標準§第61條",
  "law": "《營造安全衛生設施標準》第61條：雇主對於框式鋼管式施工架之構築，應依下列規定辦理：\n\n一、最上層及每隔五層應設置水平梁。\n\n二、框架與托架，應以水平牽條或鉤件等，防止水平滑動。\n\n三、高度超過二十公尺及架上載有物料者，主框架應在二公尺以下，且其間距應保持在一點八五公尺以下。",
