 "b-01-108": {
  "c": "塔設備高度5公尺以上應具耐震構造，防止地震損傷。",
  "w": {
   "1": "高度標準過低。",
   "2": "少於法定5公尺。",
   "3": "仍未達5公尺。"
  },
  "ref": "高壓氣體勞工安全規則§第46條",
  "law": "《高壓氣體勞工安全規則》第46條：塔（供進行反應、分離、精煉、蒸餾等製程之高壓氣體設備，以其最高位正切線至最低位正切線間之長度在五公尺以上者。）、儲槽（以儲存能力在三百立方公尺或三公噸以上之儲槽。）、冷凝器（豎式圓胴型者，以胴部長度在五公尺以上者為限。）及承液器（以內容積在五千公升以上者為限。）及支撐各該設備之支持構築物與基礎之結構，應能承受地震影響之耐震構造。",
  "g": 1
 },
 "b-01-109": {
  "c": "營建提升機適用檢查規則之標準為高度20公尺以上。",
  "w": {
   "1": "高度標準過低。",
   "2": "少於法定20公尺。",
   "3": "仍未達20公尺。"
  },
  "ref": "危險性機械及設備安全檢查規則"
 },
 "b-01-110": {
  "c": "壓力×容積乘積≥0.2時屬第一種壓力容器。",
  "w": {
   "2": "超過定義標準。",
   "3": "更高的乘積值。",
   "4": "第一種壓力容器適用條件乘積應0.2以上，不是1.0。"
  },
  "ref": "危險性機械及設備安全檢查規則§第4條",
  "law": "《危險性機械及設備安全檢查規則》第4條：本規則適用於下列容量之危險性設備：\n\n一、鍋爐：\n\n（一）最高使用壓力（表壓力，以下同）超過每平方公分一公斤，或傳熱面積超過一平方公尺（裝有內徑二十五公厘以上開放於大氣中之蒸汽管之蒸汽鍋爐、或在蒸汽部裝有內徑二十五公厘以上之Ｕ字形豎立管，其水頭壓力超過五公尺之蒸汽鍋爐，為傳熱面積超過三點五平方公尺），或胴體內徑超過三百公厘，長度超過六百公厘之蒸汽鍋爐。\n\n（二）水頭壓力超過十公尺，或傳熱面積超過八平方公尺，且液體使用溫度超過其在一大氣壓之沸點之熱媒鍋爐以外之熱水鍋爐。\n\n（三）水頭壓力超過十公尺，或傳熱面積超過八平方公尺之熱媒鍋爐。\n\n（四）鍋爐中屬貫流式者，其最高使用壓力超過每平方公分十公斤（包括具有內徑超過一百五十公厘之圓筒形集管器，或剖面積超過一百七十七平方公分之方形集管器之多管式貫流鍋爐），或其傳熱面積超過十平方公尺者（包括具有汽水分離器者，其汽水分離器之內徑超過三百公厘，或其內容積超過零點零七立方公尺者）。\n\n二、壓力容器：\n\n（一）最高使用壓力超過每平方公分一公斤，且內容積超過零點二立方公尺之第一種壓力容器。\n\n（二）最高使用壓力超過每平方公分一公斤，且胴體內徑超過五百公厘，長度超過一千公厘之第一種壓力容器。\n\n（三）以「每平方公分之公斤數」單位所表示之最高使用壓力數值與以「立方公尺」單位所表示之內容積數值之積，超過零點二之第一種壓力容器。\n\n三、高壓氣體特定設備：\n\n    指供高壓氣體之製造（含與製造相關之儲存）設備及其支持構造物（供進行反應、分離、精鍊、蒸餾等製程之塔槽類者，以其最高位正切線至最低位正切線間之長度在五公尺以上之塔，或儲存能力在三百立方公尺或三公噸以上之儲槽為一體之部分為限），其容器以「每平方公分之公斤數」單位所表示之設計壓力數值與以「立方公尺」單位所表示之內容積數值之積，超過零點零四者。但下列各款容器，不在此限：\n\n（一）泵、壓縮機、蓄壓機等相關之容器。\n\n（二）緩衝器及其他緩衝裝置相關之容器。\n\n（三）流量計、液面計及其他計測機器、濾器相關之容器。\n\n（四）使用於空調設備之容器。\n\n（五）溫度在攝氏三十五度時，表壓力在每平方公分五十公斤以下之空氣壓縮裝置之容器。\n\n（六）高壓氣體容器。\n\n（七）其他經中央主管機關指定者。\n\n四、高壓氣體容器：\n\n    指供灌裝高壓氣體之容器中，相對於地面可移動，其內容積在五百公升以上者。但下列各款容器，不在此限：\n\n（一）於未密閉狀態下使用之容器。\n\n（二）溫度在攝氏三十五度時，表壓力在每平方公分五十公斤以下之空氣壓縮裝置之容器。\n\n（三）其他經中央主管機關指定者。",
  "g": 1
 },
