  "ref": "高壓氣體勞工安全規則§第34條",
  "law": "《高壓氣體勞工安全規則》第34條：自可燃性氣體製造設備之高壓氣體設備（不含供作其他高壓氣體設備之冷卻用冷凍設備。）之外面至其他可燃性氣體製造設備之高壓氣體設備（以可燃性氣體可流通之部分為限。）應保持五公尺以上之距離，與氧氣製造設備之高壓氣體設備（以氧氣可流通之部分為限。）應保持十公尺以上距離。但依第八十條之導管設置規定設置之配管，不在此限。",
