  "ref": "危險性機械及設備安全檢查規則§第167條之1",
  "law": "《危險性機械及設備安全檢查規則》第167條之1：納入本法適用範圍前，或本規則發布施行前已設置之危險性機械及設備之檢查，得依既有危險性機械及設備安全檢查規則辦理。",
