  "ref": "職業安全衛生管理辦法§第11條",
  "law": "《職業安全衛生管理辦法》第11條：委員會置委員七人以上，除雇主為當然委員及第五款規定者外，由雇主視該事業單位之實際需要指定下列人員組成：\n\n一、職業安全衛生人員。\n\n二、事業內各部門之主管、監督、指揮人員。\n\n三、與職業安全衛生有關之工程技術人員。\n\n四、從事勞工健康服務之醫護人員。\n\n五、勞工代表。\n\n委員任期為二年，並以雇主為主任委員，綜理會務。\n\n委員會由主任委員指定一人為秘書，輔助其綜理會務。\n\n第一項第五款之勞工代表，應佔委員人數三分之一以上；事業單位設有工會者，由工會推派之；無工會組織而有勞資會議者，由勞方代表推選之；無工會組織且無勞資會議者，由勞工共同推選之。",
