  "ref": "職業安全衛生設施規則§第29條之1",
  "law": "《職業安全衛生設施規則》第29條之1：雇主使勞工於局限空間從事作業前，應先確認該局限空間內有無可能引起勞工缺氧、中毒、感電、塌陷、被夾、被捲及火災、爆炸等危害，有危害之虞者，應訂定危害防止計畫，並使現場作業主管、監視人員、作業勞工及相關承攬人依循辦理。\n\n前項危害防止計畫，應依作業可能引起之危害訂定下列事項：\n\n一、局限空間內危害之確認。\n\n二、局限空間內氧氣、危險物、有害物濃度之測定。\n\n三、通風換氣實施方式。\n\n四、電能、高溫、低溫與危害物質之隔離措施及缺氧、中毒、感電、塌陷、被夾、被捲等危害防止措施。\n\n五、作業方法及安全管制作法。\n\n六、進入作業許可程序。\n\n七、提供之測定儀器、通風換氣、防護與救援設備之檢點及維護方法。\n\n八、作業控制設施及作業安全檢點方法。\n\n九、緊急應變處置措施。",
