  "ref": "環境基本法§第3條",
  "law": "《環境基本法》第3條：基於國家長期利益，經濟、科技及社會發展均應兼顧環境保護。但經濟、科技及社會發展對環境有嚴重不良影響或有危害之虞者，應環境保護優先。"
